from pathlib import Path

import pytest


def read_public(path: str) -> str:
    """Return the text of the file `path` inside the directory `notes`.

    `notes` is relative to the current working directory. `path` is an
    untrusted request path and is resolved relative to `notes`. Paths that
    wander but end up back inside `notes` (e.g. "sub/../a.txt") are allowed,
    and files in subdirectories (e.g. "sub/b.txt") are readable.

    Returns an empty string if the file is missing, is not a regular file,
    cannot be read or decoded, or if `path` would reach anything outside
    `notes`. That covers "..", absolute paths, "sub/../../x", symlinks that
    point outside `notes`, sibling directories sharing the "notes" prefix,
    and names containing NUL bytes.
    """
    if "\x00" in path:
        return ""
    requested = Path(path)
    if requested.anchor or requested.drive:
        return ""
    depth = 0
    for part in requested.parts:
        if part == "..":
            depth -= 1
            if depth < 0:
                return ""
        elif part != ".":
            depth += 1
    try:
        base = Path("notes").resolve()
        target = (base / requested).resolve()
        if target == base or not target.is_relative_to(base):
            return ""
        if not target.is_file():
            return ""
        return target.read_text(encoding="utf-8")
    except (OSError, ValueError, RuntimeError):
        return ""


@pytest.fixture
def root(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> Path:
    notes = tmp_path / "notes"
    (notes / "sub").mkdir(parents=True)
    (notes / "a.txt").write_text("alpha", encoding="utf-8")
    (notes / "sub" / "b.txt").write_text("beta", encoding="utf-8")
    (tmp_path / "secret.txt").write_text("secret", encoding="utf-8")
    (tmp_path / "notes2").mkdir()
    (tmp_path / "notes2" / "x.txt").write_text("sibling", encoding="utf-8")
    monkeypatch.chdir(tmp_path)
    return tmp_path


def test_plain_file(root: Path) -> None:
    assert read_public("a.txt") == "alpha"


def test_subdirectory_file(root: Path) -> None:
    assert read_public("sub/b.txt") == "beta"


def test_wander_and_return(root: Path) -> None:
    assert read_public("sub/../a.txt") == "alpha"
    assert read_public("./sub/./b.txt") == "beta"
    assert read_public("sub/../sub/b.txt") == "beta"


def test_missing_file(root: Path) -> None:
    assert read_public("nope.txt") == ""
    assert read_public("sub/nope.txt") == ""
    assert read_public("nodir/a.txt") == ""


def test_directory_is_not_a_file(root: Path) -> None:
    assert read_public("sub") == ""
    assert read_public("") == ""
    assert read_public(".") == ""


def test_parent_escape(root: Path) -> None:
    assert read_public("..") == ""
    assert read_public("../secret.txt") == ""
    assert read_public("sub/../../secret.txt") == ""
    assert read_public("sub/../../notes/a.txt") == ""


def test_sibling_with_same_prefix(root: Path) -> None:
    assert read_public("../notes2/x.txt") == ""


def test_absolute_paths(root: Path) -> None:
    assert read_public(str(root / "secret.txt")) == ""
    assert read_public(str(root / "notes" / "a.txt")) == ""
    assert read_public("/etc/passwd") == ""


def test_symlink_file_escape(root: Path) -> None:
    link = root / "notes" / "link.txt"
    try:
        link.symlink_to(root / "secret.txt")
    except (OSError, NotImplementedError):
        pytest.skip("symlinks unavailable")
    assert read_public("link.txt") == ""


def test_symlink_dir_escape(root: Path) -> None:
    link = root / "notes" / "linkdir"
    try:
        link.symlink_to(root / "notes2", target_is_directory=True)
    except (OSError, NotImplementedError):
        pytest.skip("symlinks unavailable")
    assert read_public("linkdir/x.txt") == ""


def test_nul_byte(root: Path) -> None:
    assert read_public("a.txt\x00") == ""
    assert read_public("a\x00/../../secret.txt") == ""


def test_undecodable_file(root: Path) -> None:
    (root / "notes" / "bin.dat").write_bytes(b"\xff\xfe\x00\x80")
    assert read_public("bin.dat") == ""


def test_unreadable_file(root: Path) -> None:
    target = root / "notes" / "locked.txt"
    target.write_text("hidden", encoding="utf-8")
    target.chmod(0)
    try:
        try:
            target.read_text()
            pytest.skip("permissions not enforced (e.g. running as root)")
        except OSError:
            pass
        assert read_public("locked.txt") == ""
    finally:
        target.chmod(0o600)

